insert into public.recipes (id, household_id, title, tags, is_favorite, is_tried, minutes, serves, servings, hue_a, hue_b, instructions, category, subcategory, author, source_url, notes) values ('de96bcfb-7443-4f8b-8dbf-7161fd678769', '11111111-1111-4111-8111-111111111111', 'Fish and Chips', ARRAY['Protein', 'Salmon']::text[], false, false, 40, 1, 'Serves 1-2', '#C0603E', '#8A6F3F', '**Rinse and peel russet potatoes, then cut them into 10-15mm wide fries (or however you want to make them. Fries come in all different shapes and sizes).Place the fries into a pot with room temperature oil. Slowly bring the oil up to 350°F and keep stirring them until they are golden brown. Place them on paper towels to drain the excess oil.For the beer batter, combine 1 ½ cups of all purpose flour, ½ cup of corn starch, some paprika, a pinch of kosher salt, and a few twists of freshly ground pepper.Take 1 cup of that mixture to a tray, and set aside for dredging.In the main mixture add 1 tsp of baking powder and 1 Mexican beer and whisk to combine.Take your fish, dredge it in the powder mixture, and then add it to the beer batter.Slowly add to a pot with peanut or vegetable oil at 350°F, and cook for 6-9 minutes.Remove from oil, set on a paper towel to soak up the oil and to cool off. Serve with fries and enjoy!**', 'Protein', 'Salmon', 'Babish Culinary University', 'https://youtu.be/KObL442PWhQ?si=gFWPOShneI__IjTT&t=149', null);
