insert into public.recipes (id, household_id, title, tags, is_favorite, is_tried, minutes, serves, servings, hue_a, hue_b, instructions, category, subcategory, author, source_url, notes) values ('949875bb-289b-4772-a7d4-b82215f1261b', '11111111-1111-4111-8111-111111111111', 'Prik Nam Pla', ARRAY['Sauce & Dip', 'Other']::text[], true, true, 10, 2, 'Varies', '#6B7A3F', '#C0603E', 'Add all ingredients together. Store in the refrigerator and it should last a long time.', 'Sauce & Dip', 'Other', 'Pailin’s Kitchen', 'https://www.youtube.com/watch?v=isLl3m_JUx4', '- Can start with a ratio of 3:1 Fish sauce to lime juice and adjust to preference. - For more mild spice, can chop chillies into bigger pieces, remove seeds/pith, or add chopped chillies to cold water first and let sit for a few minutes. - Can use on plain/fried rice, fried eggs, pan seared fish/chicken, or, mashed potatoes. - Best fish sauce brands: Squid, Megachef, or Red Boat. Red Boat is a premium brand with more intense fish flavor, and can add sugar to help balance the fish flavor.');
